export type ParamName = keyof typeof PARAMS;
// One-dimensional geometry on the loop (TESTING.md L2.1-L2.6). Positions are metres along the
// loop; everything wraps at the loop length, which comes from hello. A Range is closed at both
// ends: a range that touches a zone's boundary counts as inside it, because "might be inside" is
// the safe reading (CLAUDE.md invariant 6).
import { PARAMS } from './params.ts';
import type { Direction } from './protocol.ts';
import type { Range, Site } from './site.ts';

export function normalise(loopM: number, p: number): number {
  if (p >= 0 && p < loopM) return p;
  const r = ((p % loopM) + loopM) % loopM;
  return r === loopM ? 0 : r;
}

// Distance travelling forward (increasing position) from `from` to `to`, in [0, loop).
export function forwardDistance(loopM: number, from: number, to: number): number {
  return normalise(loopM, to - from);
}

export interface ZoneExit {
  zoneId: string;
  fwdM: number; // distance forward to the end of the zone's stretch containing the position
  revM: number; // distance back to its start
  fwdBoundaryM: number; // loop position of each boundary
  revBoundaryM: number;
  direction: Direction; // the nearer boundary; a tie goes forward, the normal direction of travel
  distanceM: number;
}

// Where the nearest way out of the zone at `positionM` is.
export function zoneExit(site: Site, positionM: number): ZoneExit | undefined {
  const L = site.loopLengthM;
  const p = normalise(L, positionM);
  const zone = site.zoneAt(p);
  if (!zone) return undefined;
  for (const r of zone.ranges) {
    const into = forwardDistance(L, r.startM, p);
    if (into < r.lengthM || (r.lengthM >= L)) {
      const revM = into;
      const fwdM = r.lengthM - into;
      const direction: Direction = fwdM <= revM ? 'FWD' : 'REV';
      return {
        zoneId: zone.zoneId, fwdM, revM,
        fwdBoundaryM: normalise(L, r.startM + r.lengthM), revBoundaryM: normalise(L, r.startM),
        direction, distanceM: Math.min(fwdM, revM),
      };
    }
  }
  return undefined;
}

export interface ClearOptions {
  loaded: boolean;
  direction: Direction;
  speedMps?: number; // overrides the parameter, e.g. the pessimistic loaded reverse speed (L0.P)
  delayMs?: number; // overrides the supervisory command delay
}

// Time for a truck to cover `distanceM` under a supervisory command: speed by load and direction
// (autonomous forward, EXIT_ZONE reverse), plus the time the command takes to take effect.
export function timeToClearMs(distanceM: number, o: ClearOptions): number {
  const speed = o.speedMps ?? speedFor(o.loaded, o.direction);
  const delay = o.delayMs ?? PARAMS.supervisoryDelayMax.value;
  return (Math.max(0, distanceM) / speed) * 1000 + delay;
}

function speedFor(loaded: boolean, direction: Direction): number {
  if (direction === 'FWD') return loaded ? PARAMS.autoSpeedLoaded.value : PARAMS.autoSpeedEmpty.value;
  return loaded ? PARAMS.reverseSpeedLoaded.value : PARAMS.reverseSpeedEmpty.value;
}

// Everywhere a truck could be `elapsedMs` after it was at `anchorM`, moving forward at up to
// `fwdMps` or back at up to `revMps`. Never more than the whole loop.
export function reachableRange(loopM: number, anchorM: number, elapsedMs: number, fwdMps: number, revMps: number): Range {
  const t = Math.max(0, elapsedMs) / 1000;
  const back = Math.max(0, revMps) * t;
  const ahead = Math.max(0, fwdMps) * t;
  if (back + ahead >= loopM) return { startM: 0, lengthM: loopM };
  return { startM: normalise(loopM, anchorM - back), lengthM: back + ahead };
}

// Closed-interval overlap on the loop, with wrap.
export function rangesOverlap(loopM: number, a: Range, b: Range): boolean {
  if (a.lengthM >= loopM || b.lengthM >= loopM) return true;
  const a0 = normalise(loopM, a.startM), a1 = a0 + a.lengthM;
  const b0 = normalise(loopM, b.startM), b1 = b0 + b.lengthM;
  for (const shift of [-loopM, 0, loopM]) {
    if (a0 <= b1 + shift && b0 + shift <= a1) return true;
  }
  return false;
}

// Zone ids the range touches, in route order.
export function zonesOverlapping(site: Site, range: Range): string[] {
  return site.zones.filter((z) => z.ranges.some((r) => rangesOverlap(site.loopLengthM, range, r))).map((z) => z.zoneId);
}
// The site as hello describes it (CLAUDE.md invariant 7): route, zones, loop length and vehicles.
// Nothing here knows this particular mine. A route that doesn't add up is reported in `issues`
// rather than silently trusted; a hello with no usable route is refused.
import type { Hello, RouteSegment } from './protocol.ts';

const EPS_M = 0.01;

export interface Range {
  startM: number;
  lengthM: number; // startM + lengthM may pass the loop end, meaning the range wraps
}

export interface Segment {
  segmentId: string;
  zoneId: string;
  kind: string;
  startM: number;
  lengthM: number;
}

export interface Zone {
  zoneId: string;
  ranges: Range[];
  lengthM: number;
  segmentIds: string[];
  kinds: string[];
}

export interface Site {
  readonly siteId: string;
  readonly loopLengthM: number;
  readonly segments: readonly Segment[];
  readonly zones: readonly Zone[]; // in the order they first appear along the route
  readonly vehicles: readonly string[];
  segment(segmentId: string): Segment | undefined;
  zone(zoneId: string): Zone | undefined;
  toLoop(segmentId: string, offsetM: number): number | undefined;
  zoneAt(positionM: number): Zone | undefined;
  bayZones(): Zone[];
}

export class SiteError extends Error {}

export function buildSite(hello: Hello): { site: Site; issues: string[] } {
  const loop = hello.loop_length_m;
  if (!Array.isArray(hello.route) || hello.route.length === 0) throw new SiteError('hello has no route');
  if (!(loop > 0)) throw new SiteError(`hello has no usable loop length (${loop})`);

  const issues: string[] = [];
  const segments = [...hello.route].sort((a, b) => a.start_m - b.start_m).map(toSegment);

  const seen = new Set<string>();
  for (const s of segments) {
    if (seen.has(s.segmentId)) issues.push(`duplicate segment id ${s.segmentId}`);
    seen.add(s.segmentId);
  }
  for (let i = 1; i < segments.length; i++) {
    const prev = segments[i - 1]!, cur = segments[i]!;
    const prevEnd = prev.startM + prev.lengthM;
    if (cur.startM > prevEnd + EPS_M) issues.push(`gap of ${round(cur.startM - prevEnd)} m between ${prev.segmentId} and ${cur.segmentId}`);
    if (cur.startM < prevEnd - EPS_M) issues.push(`${prev.segmentId} and ${cur.segmentId} overlap by ${round(prevEnd - cur.startM)} m`);
  }
  const covered = segments.reduce((sum, s) => sum + s.lengthM, 0);
  if (Math.abs(covered - loop) > EPS_M) issues.push(`route covers ${round(covered)} m of a ${round(loop)} m loop`);

  const zones = buildZones(segments, loop);
  for (const z of zones) {
    if (z.ranges.length > 1) issues.push(`zone ${z.zoneId} is in ${z.ranges.length} separate stretches`);
  }

  const bySegment = new Map(segments.map((s) => [s.segmentId, s]));
  const byZone = new Map(zones.map((z) => [z.zoneId, z]));
  const norm = (p: number) => ((p % loop) + loop) % loop;

  const site: Site = {
    siteId: hello.site_id,
    loopLengthM: loop,
    segments,
    zones,
    vehicles: [...hello.vehicles],
    segment: (id) => bySegment.get(id),
    zone: (id) => byZone.get(id),
    toLoop(segmentId, offsetM) {
      const s = bySegment.get(segmentId);
      return s && Number.isFinite(offsetM) ? s.startM + offsetM : undefined;
    },
    zoneAt(positionM) {
      if (!Number.isFinite(positionM)) return undefined;
      const p = norm(positionM);
      const s = segments.find((x) => p >= x.startM - EPS_M / 2 && p < x.startM + x.lengthM);
      return s && byZone.get(s.zoneId);
    },
    bayZones: () => zones.filter((z) => z.kinds.includes('bay')),
  };
  return { site, issues };
}

function toSegment(r: RouteSegment): Segment {
  return { segmentId: r.segment_id, zoneId: r.zone_id, kind: r.kind, startM: r.start_m, lengthM: r.length_m };
}

// Consecutive segments of one zone make a range; a zone at both ends of the route is one range
// across the wrap.
function buildZones(segments: Segment[], loop: number): Zone[] {
  const runs: Array<{ zoneId: string; range: Range }> = [];
  for (const s of segments) {
    const last = runs.at(-1);
    if (last && last.zoneId === s.zoneId && Math.abs(last.range.startM + last.range.lengthM - s.startM) <= EPS_M) {
      last.range.lengthM += s.lengthM;
    } else {
      runs.push({ zoneId: s.zoneId, range: { startM: s.startM, lengthM: s.lengthM } });
    }
  }
  const first = runs[0], last = runs.at(-1);
  if (first && last && runs.length > 1 && first.zoneId === last.zoneId &&
      Math.abs(first.range.startM) <= EPS_M && Math.abs(last.range.startM + last.range.lengthM - loop) <= EPS_M) {
    last.range.lengthM += first.range.lengthM;
    runs.shift();
  }

  const order: string[] = [];
  for (const s of segments) if (!order.includes(s.zoneId)) order.push(s.zoneId);
  return order.map((zoneId) => {
    const mine = segments.filter((s) => s.zoneId === zoneId);
    const ranges = runs.filter((r) => r.zoneId === zoneId).map((r) => r.range).sort((a, b) => a.startM - b.startM);
    return {
      zoneId,
      ranges,
      lengthM: ranges.reduce((sum, r) => sum + r.lengthM, 0),
      segmentIds: mine.map((s) => s.segmentId),
      kinds: [...new Set(mine.map((s) => s.kind))],
    };
  });
}

const round = (x: number) => Math.round(x * 100) / 100;
// Injected time (CLAUDE.md invariant 1). This is the only module that touches the wall clock or
// timers; everything else takes a Clock. Times are Unix milliseconds.

export interface TimerHandle {
  readonly id: number;
}

export interface Clock {
  now(): number;
  setTimeout(fn: () => void, ms: number): TimerHandle;
  clearTimeout(handle: TimerHandle): void;
}

export class SystemClock implements Clock {
  readonly #timers = new Map<number, ReturnType<typeof globalThis.setTimeout>>();
  #nextId = 1;

  now(): number {
    return Date.now();
  }

  setTimeout(fn: () => void, ms: number): TimerHandle {
    const id = this.#nextId++;
    this.#timers.set(id, globalThis.setTimeout(() => { this.#timers.delete(id); fn(); }, ms));
    return { id };
  }

  clearTimeout(handle: TimerHandle): void {
    const t = this.#timers.get(handle.id);
    if (t !== undefined) globalThis.clearTimeout(t);
    this.#timers.delete(handle.id);
  }
}

interface Pending {
  id: number;
  due: number;
  fn: () => void;
}

// For tests: time moves only when advanced, and due timers run in order (by due time, then by the
// order they were set), each seeing now() equal to its own due time.
export class ManualClock implements Clock {
  #now: number;
  #nextId = 1;
  #pending: Pending[] = [];

  constructor(start: number) {
    this.#now = start;
  }

  now(): number {
    return this.#now;
  }

  setTimeout(fn: () => void, ms: number): TimerHandle {
    const id = this.#nextId++;
    this.#pending.push({ id, due: this.#now + Math.max(0, ms), fn });
    return { id };
  }

  clearTimeout(handle: TimerHandle): void {
    this.#pending = this.#pending.filter((p) => p.id !== handle.id);
  }

  pending(): number {
    return this.#pending.length;
  }

  advance(ms: number): void {
    if (ms < 0) throw new RangeError('a clock cannot go backwards');
    const target = this.#now + ms;
    for (let fired = 0; ; fired++) {
      if (fired > 1_000_000) throw new Error('runaway timers: over a million fired in one advance');
      const next = this.#nextDue(target);
      if (!next) break;
      this.#pending = this.#pending.filter((p) => p !== next);
      this.#now = next.due;
      next.fn();
    }
    this.#now = target;
  }

  #nextDue(target: number): Pending | undefined {
    let best: Pending | undefined;
    for (const p of this.#pending) {
      if (p.due <= target && (!best || p.due < best.due || (p.due === best.due && p.id < best.id))) best = p;
    }
    return best;
  }
}

// A time as an ISO 8601 string, for log lines. Here because this is the one module allowed to use
// Date; it formats the time it is given and never reads the clock itself.
export function isoTime(ms: number): string {
  return new Date(ms).toISOString();
}

// The gateway link: one connection to the site per service, that recovers on its own and never
// lets an old picture pass for a current one (TESTING.md L2.40-L2.44, L6.1, L6.2, L6.4).
//
// - TLS to GATEWAY_HOST:GATEWAY_PORT, logging in with GATEWAY_EMAIL. Credentials come from the
//   environment only, and are never logged.
// - Reconnects with capped, jittered exponential backoff. A login accepted and then closed before
//   hello is a site-link outage (PROTOCOL.md §1.1), handled the same way.
// - Down after PARAMS.linkDownAfter with no heartbeat: the connection is dropped and redialled, and
//   fleet state is told, so nothing is shown as live meanwhile.
// - Every line goes to fleet state; then to subscribers (the command registry). On hello the
//   registry replays its in-flight commands.
// - Time and randomness are injected: backoff and watchdogs run on the Clock.
import { connect as tlsConnect } from 'node:tls';
import { isIP } from 'node:net';
import { StringDecoder } from 'node:string_decoder';
import type { Clock, TimerHandle } from './clock.ts';
import type { FleetState } from './fleet.ts';
import { parseLine } from './ingest.ts';
import { PARAMS } from './params.ts';
import { AUTH_ERRORS, type AuthErrorReason, type ClientMessage, type CommandMessage, type Hello } from './protocol.ts';
import type { CommandRegistry, CommandTransport } from './registry.ts';

// ---- transport ----

export interface LinkSocket {
  write(line: string): void; // one NDJSON line, without the newline
  close(): void;             // no onClose follows a close we asked for
}

export interface DialHandlers {
  onLine(line: string): void;
  onClose(reason: string): void;
}

export type Dialer = (h: DialHandlers) => LinkSocket;

// PROTOCOL.md §1: the gateway closes a connection that sends a line over 64 KiB. We refuse to send
// one, and treat a peer that sends a far longer one as broken.
export const MAX_LINE_BYTES = 64 * 1024;
const MAX_BUFFER_CHARS = 16 * MAX_LINE_BYTES;

export interface TlsTarget {
  host: string;
  port: number;
  ca?: string | Buffer; // tests only: the fake's throwaway certificate. Production uses the system's trust store
}

export function tlsDialer(t: TlsTarget): Dialer {
  return (h) => {
    const sock = tlsConnect({ host: t.host, port: t.port, ...(isIP(t.host) ? {} : { servername: t.host }), ...(t.ca ? { ca: t.ca } : {}) });
    sock.setNoDelay(true);
    const decoder = new StringDecoder('utf8');
    let buf = '';
    let done = false;
    let why: string | null = null;
    const finish = (reason: string) => {
      if (done) return;
      done = true;
      h.onClose(reason);
    };
    sock.on('data', (chunk: Buffer) => {
      buf += decoder.write(chunk);
      let start = 0;
      for (let i = buf.indexOf('\n'); i >= 0 && !done; i = buf.indexOf('\n', start)) {
        const end = i > start && buf.charCodeAt(i - 1) === 13 ? i - 1 : i;
        h.onLine(buf.slice(start, end));
        start = i + 1;
      }
      buf = start === 0 ? buf : buf.slice(start);
      if (buf.length > MAX_BUFFER_CHARS && !done) {
        sock.destroy();
        finish(`the gateway sent a line over ${MAX_BUFFER_CHARS} characters`);
      }
    });
    sock.on('error', (e: Error) => { why = e.message; });
    sock.on('close', () => finish(why ? `connection failed: ${why}` : 'connection closed by the gateway'));
    return {
      write: (line) => { if (!done) sock.write(line + '\n'); },
      close: () => { done = true; sock.destroy(); },
    };
  };
}

export interface LinkConfig { host: string; port: number; email: string }

// GATEWAY_HOST, GATEWAY_PORT and GATEWAY_EMAIL (BRIEF.md). The error names what is missing and
// never echoes a value.
export function linkConfigFromEnv(env: Record<string, string | undefined>): LinkConfig {
  const missing = ['GATEWAY_HOST', 'GATEWAY_PORT', 'GATEWAY_EMAIL'].filter((k) => !env[k] || env[k]!.trim() === '');
  if (missing.length > 0) throw new Error(`missing environment variables: ${missing.join(', ')}`);
  const port = Number(env.GATEWAY_PORT);
  if (!Number.isInteger(port) || port <= 0 || port > 65_535) throw new Error('GATEWAY_PORT is not a port number');
  return { host: env.GATEWAY_HOST!.trim(), port, email: env.GATEWAY_EMAIL!.trim() };
}

// ---- the link ----

export type LinkState = 'idle' | 'connecting' | 'up' | 'down' | 'stopped';

export interface LinkStatus {
  state: LinkState;
  sinceMs: number;                  // on the injected clock
  reason: string;                   // why it is in this state, in words
  failures: number;                 // consecutive attempts since the last hello
  nextAttemptAtMs: number | null;
  dials: number;                    // connections opened, ever
  lastHeartbeatMs: number | null;
  authError: AuthErrorReason | null;
}

export type LinkEvent =
  | { type: 'status'; status: LinkStatus }
  | { type: 'up'; hello: Hello }
  | { type: 'down'; reason: string }        // only on leaving 'up'
  | { type: 'message'; msg: Record<string, unknown> & { type: string } }
  | { type: 'alarm'; message: string };

export interface LinkOptions {
  clock: Clock;
  fleet: FleetState;
  dial: Dialer;
  email: string;
  random?: () => number; // [0, 1); injected so backoff is reproducible in tests
}

const BUSY: ReadonlySet<string> = new Set<AuthErrorReason>(['TOO_MANY_CONNECTIONS', 'SERVER_FULL']);

export class GatewayLink implements CommandTransport {
  readonly #clock: Clock;
  readonly #fleet: FleetState;
  readonly #dial: Dialer;
  readonly #email: string;
  readonly #random: () => number;
  readonly #listeners = new Set<(e: LinkEvent) => void>();
  #socket: LinkSocket | null = null;
  #gen = 0;
  #status: LinkStatus;
  #retryTimer: TimerHandle | null = null;
  #helloTimer: TimerHandle | null = null;
  #watchdog: TimerHandle | null = null;
  #busy = false;

  constructor(o: LinkOptions) {
    this.#clock = o.clock;
    this.#fleet = o.fleet;
    this.#dial = o.dial;
    this.#email = o.email;
    this.#random = o.random ?? Math.random;
    this.#status = { state: 'idle', sinceMs: o.clock.now(), reason: 'not started', failures: 0, nextAttemptAtMs: null, dials: 0, lastHeartbeatMs: null, authError: null };
  }

  subscribe(fn: (e: LinkEvent) => void): () => void {
    this.#listeners.add(fn);
    return () => this.#listeners.delete(fn);
  }

  status(): LinkStatus {
    return { ...this.#status };
  }

  isUp(): boolean {
    return this.#status.state === 'up';
  }

  // Starts the one connection. Calling it again while running does nothing (L6.4).
  start(): void {
    if (this.#status.state !== 'idle' && this.#status.state !== 'stopped') return;
    this.#status.authError = null;
    this.#status.failures = 0;
    this.#connect();
  }

  stop(): void {
    this.#clearTimers();
    this.#dropSocket();
    this.#set('stopped', 'stopped');
  }

  // Commands, from the registry only.
  send(msg: CommandMessage): boolean {
    return this.#write(msg);
  }

  // Drive messages, from the drive relay (a later task). Never queued, never re-sent: a message
  // that can't go now is dropped, and silence lets the deadman stop the truck.
  sendDrive(msg: Extract<ClientMessage, { type: 'drive' }>): boolean {
    return this.#write(msg);
  }

  #write(msg: ClientMessage): boolean {
    if (!this.isUp() || !this.#socket) return false;
    const line = JSON.stringify(msg);
    if (Buffer.byteLength(line, 'utf8') > MAX_LINE_BYTES) return false;
    this.#socket.write(line);
    return true;
  }

  // ---- connection lifecycle ----

  #connect(): void {
    this.#retryTimer = null;
    if (this.#socket) return; // one connection at a time, always
    const gen = ++this.#gen;
    this.#status.dials++;
    this.#status.nextAttemptAtMs = null;
    this.#set('connecting', `connecting (attempt ${this.#status.failures + 1})`);
    const socket = this.#dial({
      onLine: (line) => { if (gen === this.#gen) this.#line(line); },
      onClose: (reason) => { if (gen === this.#gen) this.#closed(reason); },
    });
    if (gen !== this.#gen) { socket.close(); return; } // closed while dialling
    this.#socket = socket;
    this.#helloTimer = this.#clock.setTimeout(() => {
      this.#helloTimer = null;
      if (gen === this.#gen && this.#status.state === 'connecting') this.#fail(`no hello within ${PARAMS.helloTimeout.value / 1000} s of logging in`);
    }, PARAMS.helloTimeout.value);
    socket.write(JSON.stringify({ type: 'auth', email: this.#email }));
  }

  #line(line: string): void {
    const p = parseLine(line);
    if (!p.ok) { this.#fleet.ingestLine(line); return; } // counted as data quality there
    const m = p.msg;
    if (m.type === 'auth_error') { this.#authError(m.reason); return; }
    if (m.type === 'hello') { this.#hello(m as unknown as Hello); return; }
    this.#fleet.ingest(m);
    if (m.type === 'heartbeat') this.#heartbeat();
    this.#emit({ type: 'message', msg: m });
  }

  #hello(h: Hello): void {
    if (this.#helloTimer) { this.#clock.clearTimeout(this.#helloTimer); this.#helloTimer = null; }
    this.#fleet.newConnection();
    this.#fleet.ingest(h);
    this.#status.failures = 0;
    this.#busy = false;
    this.#heartbeat();
    this.#set('up', 'connected');
    this.#fleet.setLink(true, 'connected');
    this.#emit({ type: 'up', hello: h });
  }

  #heartbeat(): void {
    this.#status.lastHeartbeatMs = this.#clock.now();
    if (this.#watchdog) this.#clock.clearTimeout(this.#watchdog);
    const gen = this.#gen;
    this.#watchdog = this.#clock.setTimeout(() => {
      this.#watchdog = null;
      if (gen === this.#gen && this.#status.state === 'up') {
        this.#fail(`no heartbeat for ${PARAMS.linkDownAfter.value / 1000} s`);
      }
    }, PARAMS.linkDownAfter.value);
  }

  #authError(reason: unknown): void {
    const r = (AUTH_ERRORS as readonly unknown[]).includes(reason) ? (reason as AuthErrorReason) : null;
    this.#status.authError = r;
    if (r !== null && BUSY.has(r)) {
      this.#busy = true;
      this.#fail(`the gateway refused the login: ${r === 'SERVER_FULL' ? 'it is full' : 'too many connections to this site'}; trying again`);
      return;
    }
    // Anything else will not fix itself by retrying: stop and say so.
    this.#clearTimers();
    this.#dropSocket();
    const message = `The gateway refused the login (${String(reason)}). The site link is stopped until someone fixes the configuration.`;
    this.#set('stopped', message);
    this.#fleet.setLink(false, message);
    this.#emit({ type: 'alarm', message });
  }

  #closed(reason: string): void {
    this.#socket = null;
    if (this.#status.state === 'connecting') {
      this.#fail(`login accepted, then closed before hello (site link outage): ${reason}`);
    } else {
      this.#fail(reason);
    }
  }

  // Lose the connection and schedule the next attempt.
  #fail(reason: string): void {
    const wasUp = this.#status.state === 'up';
    this.#clearTimers();
    this.#dropSocket();
    if (this.#status.state === 'stopped') return;
    const delay = this.#backoff(this.#status.failures);
    this.#status.failures++;
    this.#status.nextAttemptAtMs = this.#clock.now() + delay;
    this.#set('down', reason);
    this.#fleet.setLink(false, `site link down: ${reason}`);
    if (wasUp) this.#emit({ type: 'down', reason });
    this.#retryTimer = this.#clock.setTimeout(() => this.#connect(), delay);
  }

  // Exponential from the base, capped, with "equal jitter": between half and all of the step, so
  // two services never synchronise and a retry is never instant.
  #backoff(failures: number): number {
    const base = this.#busy ? PARAMS.linkBackoffBusyBase.value : PARAMS.linkBackoffBase.value;
    const cap = this.#busy ? PARAMS.linkBackoffBusyMax.value : PARAMS.linkBackoffMax.value;
    const step = Math.min(cap, base * 2 ** Math.min(failures, 20));
    return Math.round(step / 2 + this.#random() * (step / 2));
  }

  #dropSocket(): void {
    this.#gen++;
    const s = this.#socket;
    this.#socket = null;
    s?.close();
  }

  #clearTimers(): void {
    for (const t of [this.#retryTimer, this.#helloTimer, this.#watchdog]) if (t) this.#clock.clearTimeout(t);
    this.#retryTimer = this.#helloTimer = this.#watchdog = null;
  }

  #set(state: LinkState, reason: string): void {
    if (this.#status.state !== state) this.#status.sinceMs = this.#clock.now();
    this.#status.state = state;
    this.#status.reason = reason;
    this.#emit({ type: 'status', status: this.status() });
  }

  #emit(e: LinkEvent): void {
    for (const fn of this.#listeners) fn(e);
  }
}

// The registry hears everything the link hears, after fleet state has taken it in.
export function attachRegistry(link: GatewayLink, registry: CommandRegistry): () => void {
  return link.subscribe((e) => {
    if (e.type === 'up') registry.linkUp(e.hello);
    else if (e.type === 'down') registry.linkDown(e.reason);
    else if (e.type === 'message') registry.message(e.msg);
  });
}

