28	  drain: { emptyPctPerKm: number | null; loadedPctPerKm: number | null; emptyEvidenceM: number; loadedEvidenceM: number };
29	  ratioToFleet: { empty: number | null; loaded: number | null };
30	  drainHigh: boolean;
