153	}
154	
155	interface ZoneRecord {
156	  zoneId: string;
157	  status: ZoneStatus | null;
158	  reason: string | null;
159	  effectiveAtMs: number | null;
160	  updatedServerMs: number | null;
161	}
162	
163	const MOVING_STATES: ReadonlySet<string> = new Set<VehicleState>(['TRAMMING', 'MANUAL']);
164	
165	export class FleetState {
166	  readonly #clock: Clock;
167	  #site: Site | undefined;
168	  #routeKey = '';
169	  #roster: string[] = [];
170	  #trucks = new Map<string, Truck>();
171	  #zones = new Map<string, ZoneRecord>();
172	  #offsets: number[] = [];
173	  #lastHeartbeat: { serverMs: number; atLocal: number } | null = null;
174	  #dqTotal: Record<string, number> = {};
175	  #dqConnection: Record<string, number> = {};
176	  #listeners = new Set<(e: FleetEvent) => void>();
177	  #timer: TimerHandle | null = null;
178	  #link: { up: boolean; sinceLocal: number; reason: string } | null = null;
179	
180	  constructor(clock: Clock) {
181	    this.#clock = clock;
182	  }
183	
184	  get site(): Site | undefined { return this.#site; }
185	
186	  subscribe(fn: (e: FleetEvent) => void): () => void {
187	    this.#listeners.add(fn);
188	    return () => this.#listeners.delete(fn);
189	  }
190	
191	  // Server time now: the injected clock plus the learned offset. The offset is the largest of the
192	  // recent samples, because delay in transit only ever makes a sample too small.
193	  serverNow(): number {
194	    return this.#clock.now() + this.#offset();
195	  }
196	
197	  // The gateway link says whether it is up (TESTING.md L2.43). While it is down nothing is shown as
198	  // live, however recent its last message: the picture is ageing and nobody can see it change.
199	  setLink(up: boolean, reason: string): void {
200	    if (this.#link && this.#link.up === up && this.#link.reason === reason) return;
201	    if (!this.#link || this.#link.up !== up) this.#link = { up, sinceLocal: this.#clock.now(), reason };
202	    else this.#link.reason = reason;
203	    this.tick();
204	  }
205	
206	  // One truck's view, without building the whole snapshot. Undefined for a truck never heard of.
207	  truck(vehicleId: string): TruckView | undefined {
208	    const t = this.#trucks.get(vehicleId);
209	    if (!t) return undefined;
210	    const fleet = this.#fleetDrain();
211	    return this.#view(t, this.#clock.now(), fleet);
212	  }
213	
214	  // A new connection to the gateway: per-connection counts start again.
215	  newConnection(): void {
216	    this.#dqConnection = {};
217	  }
218	
219	  ingestLine(line: string): void {
220	    const p = parseLine(line);
221	    if (!p.ok) { this.#linkDq(p.reason, line); return; }
222	    this.#dispatch(p.msg);
223	  }
224	
225	  ingest(message: unknown): void {
226	    const p = classify(message);
227	    if (!p.ok) { this.#linkDq(p.reason, String(message)); return; }
228	    this.#dispatch(p.msg);
229	  }
230	
231	  // Re-evaluates everything that changes with time alone (old, silent, contradicted, battery) and
232	  // emits what changed. Snapshots are always correct without it; events need it.
233	  tick(): void {
234	    for (const t of this.#trucks.values()) this.#evaluate(t);
235	  }
236	
237	  start(intervalMs: number = PARAMS.heartbeatInterval.value / 8): void {
238	    this.stop();
239	    const loop = () => { this.tick(); this.#timer = this.#clock.setTimeout(loop, intervalMs); };
240	    this.#timer = this.#clock.setTimeout(loop, intervalMs);
241	  }
242	
243	  stop(): void {
244	    if (this.#timer) this.#clock.clearTimeout(this.#timer);
245	    this.#timer = null;
246	  }
247	
248	  snapshot(): FleetSnapshot {
249	    const now = this.#clock.now();
250	    const site = this.#site;
251	    const fleet = this.#fleetDrain();
252	    const trucks = this.#orderedTrucks().map((t) => this.#view(t, now, fleet));
253	    const zoneIds = [...(site?.zones.map((z) => z.zoneId) ?? []), ...[...this.#zones.keys()].filter((id) => !site?.zone(id))];
254	    const zones = [...new Set(zoneIds)].map((id): ZoneView => {
255	      const z = this.#zones.get(id);
256	      const eff = z?.effectiveAtMs ?? null;
257	      return {
258	        zoneId: id,
259	        status: z?.status ?? null,
260	        reason: z?.reason ?? null,
261	        effectiveAtMs: eff,
262	        msUntilEffective: eff === null ? null : eff - this.serverNow(),
263	        updatedServerMs: z?.updatedServerMs ?? null,
264	        trucksMightBeIn: trucks.filter((t) => t.range === null || t.mightBeIn.includes(id)).map((t) => t.vehicleId),
265	      };
266	    });
267	    const hb = this.#lastHeartbeat;
268	    const hbAge = hb ? now - hb.atLocal : null;
269	    const link = this.#link;
270	    return {
271	      atServerMs: this.serverNow(),
272	      link: { up: link?.up ?? null, sinceServerMs: link ? link.sinceLocal + this.#offset() : null, reason: link?.reason ?? 'not connected yet' },
273	      siteId: site?.siteId ?? null,
274	      loopLengthM: site?.loopLengthM ?? null,
275	      heartbeat: { lastServerMs: hb?.serverMs ?? null, ageMs: hbAge, stale: hbAge === null || hbAge >= PARAMS.linkDownAfter.value },
276	      zones,
277	      trucks,
278	      fleetDrain: { emptyPctPerKm: perKm(fleet.emptyPctPerM), loadedPctPerKm: perKm(fleet.loadedPctPerM) },
279	      dataQuality: { total: { ...this.#dqTotal }, connection: { ...this.#dqConnection } },
280	    };
281	  }
282	
283	  // ---- dispatch ----
284	
285	  #dispatch(m: Record<string, unknown> & { type: string }): void {
286	    const st = serverTimeOf(m);
287	    if (st !== undefined) this.#sample(st);
288	    switch (m.type) {
289	      case 'telemetry': this.#telemetry(m); break;
290	      case 'heartbeat':
291	        if (st === undefined) this.#linkDq('bad_message', 'heartbeat without server_time_ms');
292	        else this.#lastHeartbeat = { serverMs: st, atLocal: this.#clock.now() };
293	        break;
294	      case 'hello': this.#hello(m as unknown as Hello); break;
295	      case 'zone_event': this.#zoneEvent(m, st); break;
296	      // Commands, leases and drive refusals belong to the command registry and the gateway link;
297	      // here they only contribute server time.
298	      case 'command_ack': case 'lease_event': case 'drive_rejected': case 'auth_error': break;
299	      default: this.#linkDq('unknown_type', m.type);
300	    }
301	  }
302	
303	  #hello(h: Hello): void {
304	    let built: { site: Site; issues: string[] };
305	    try {
306	      built = buildSite(h);
307	    } catch (e) {
308	      this.#linkDq('hello:invalid', e instanceof SiteError ? e.message : String(e));
309	      return;
310	    }
311	    const routeKey = JSON.stringify([h.loop_length_m, h.route]);
312	    if (this.#site && routeKey !== this.#routeKey) {
313	      // A different route: positions recorded against the old one mean nothing now.
314	      for (const t of this.#trucks.values()) { delete t.position; t.still = null; t.drainPrev = null; }
315	    }
316	    this.#site = built.site;
317	    this.#routeKey = routeKey;
318	    for (const i of built.issues) this.#linkDq('hello:route_issue', i);
319	    this.#emit({ type: 'site', siteId: built.site.siteId, issues: built.issues, atServerMs: this.serverNow() });
320	
321	    this.#roster = Array.isArray(h.vehicles) ? h.vehicles.filter((v): v is string => typeof v === 'string') : [];
322	    for (const id of this.#roster) if (!this.#trucks.has(id)) this.#trucks.set(id, new Truck(id));
323	    for (const t of this.#trucks.values()) t.onRoster = this.#roster.includes(t.vehicleId);
324	
325	    // The snapshot replaces what we knew. A route zone missing from it is unknown, not open.
326	    const at = serverTimeOf(h as unknown as Record<string, unknown>) ?? this.serverNow();
327	    const listed = new Set<string>();
328	    for (const raw of Array.isArray(h.zones) ? h.zones : []) {
329	      const { zone, issues } = validateZone(raw);
330	      for (const i of issues) this.#linkDq(i, JSON.stringify(raw));
331	      if (!zone) continue;
332	      listed.add(zone.zoneId);
333	      this.#setZone({ ...zone, updatedServerMs: at });
334	    }
335	    for (const z of built.site.zones) {
336	      if (!listed.has(z.zoneId)) this.#setZone({ zoneId: z.zoneId, status: null, reason: null, effectiveAtMs: null, updatedServerMs: at });
337	    }
338	    this.tick();
339	  }
340	
341	  #zoneEvent(m: Record<string, unknown>, st: number | undefined): void {
342	    const { zone, issues } = validateZone(m);
343	    for (const i of issues) this.#linkDq(i, JSON.stringify(m));
344	    if (!zone) return;
345	    const prev = this.#zones.get(zone.zoneId);
346	    if (st !== undefined && prev?.updatedServerMs != null && st < prev.updatedServerMs) {
347	      this.#linkDq('zone_event:stale', `${zone.zoneId} ${zone.status} at ${st}, after ${prev.updatedServerMs}`);
348	      return;
349	    }
350	    this.#setZone({ ...zone, updatedServerMs: st ?? this.serverNow() });
351	  }
352	
353	  #setZone(z: ZoneRecord): void {
354	    const prev = this.#zones.get(z.zoneId);
355	    this.#zones.set(z.zoneId, z);
356	    if (!prev || prev.status !== z.status || prev.effectiveAtMs !== z.effectiveAtMs || prev.reason !== z.reason) {
357	      this.#emit({ type: 'zone', zoneId: z.zoneId, status: z.status, reason: z.reason, effectiveAtMs: z.effectiveAtMs, atServerMs: this.serverNow() });
358	    }
359	  }
360	
361	  // ---- telemetry ----
362	
363	  #telemetry(m: Record<string, unknown>): void {
364	    const v = validateTelemetry(m, this.#site);
365	    if (!v.fields) { this.#linkDq('bad_message', `telemetry: ${v.issues.map((i) => i.detail).join('; ')}`); return; }
366	    const f = v.fields;
367	    const t = this.#truckFor(f.vehicleId);
368	    if (f.seq === undefined) {
369	      this.#truckDq(t, 'seq:invalid', v.issues.find((i) => i.field === 'seq')?.detail ?? 'seq unusable');
370	      return;
371	    }
372	    if (f.tDeviceMs === undefined) {
373	      const i = v.issues.find((x) => x.field === 't_device_ms');
374	      if (i) this.#truckDq(t, i.kind, i.detail);
375	    }
376	    const body = JSON.stringify(m);
377	    const verdict = this.#order(t, f.seq, f.tDeviceMs, body);
378	    if (verdict === 'duplicate') { t.radio.duplicates++; return; }
379	    if (verdict === 'older') { t.radio.older++; return; }
380	    if (verdict === 'conflict') { this.#truckDq(t, 'seq:conflict', `seq ${f.seq} arrived twice with different contents`); return; }
381	    for (const i of v.issues) if (i.field !== 't_device_ms') this.#truckDq(t, i.kind, i.detail);
382	    this.#apply(t, f);
383	    this.#evaluate(t);
384	  }
385	
386	  // Order by seq within a controller run (CONTEXT.md assumption 3).
387	  #order(t: Truck, seq: number, tDev: number | undefined, body: string): 'apply' | 'duplicate' | 'older' | 'conflict' {
388	    const window = PARAMS.reorderWindow.value;
389	    const run = t.run;
390	    const begin = (index: number) => {
391	      t.run = { index, startTDev: tDev, maxSeq: seq, tDevAtMax: tDev, seen: new Map([[seq, body]]) };
392	    };
393	    if (!run) { begin(0); return 'apply'; }
394	    const seen = run.seen.get(seq);
395	    if (seen !== undefined) return seen === body ? 'duplicate' : 'conflict';
396	    if (seq > run.maxSeq) {
397	      // A late message from the previous run can carry a higher seq than the new run has reached;
398	      // its device time gives it away.
399	      if (t.restarts > 0 && tDev !== undefined && run.startTDev !== undefined && tDev < run.startTDev) return 'older';
400	      run.seen.set(seq, body);
401	      run.maxSeq = seq;
402	      run.tDevAtMax = tDev;
403	      for (const s of run.seen.keys()) if (s < seq - 4 * window) run.seen.delete(s);
404	      return 'apply';
405	    }
406	    const forward = tDev !== undefined && run.tDevAtMax !== undefined && tDev > run.tDevAtMax;
407	    if (forward && (run.maxSeq - seq > window || seq <= window)) {
408	      const from = run.maxSeq;
409	      t.restarts++;
410	      begin(run.index + 1);
411	      t.drainPrev = null;
412	      t.dq.controller_restart = (t.dq.controller_restart ?? 0) + 1;
413	      this.#emit({ type: 'controller_restart', vehicleId: t.vehicleId, detail: `seq went from ${from} to ${seq} while its clock moved forward: controller restarted`, atServerMs: this.serverNow() });
414	      return 'apply';
415	    }
416	    run.seen.set(seq, body);
417	    return 'older';
418	  }
419	
420	  #apply(t: Truck, f: TelemetryFields): void {
421	    const at = this.#clock.now();
422	    t.lastAccepted = at;
423	    t.radio.applied++;
424	    const set = <K extends 'state' | 'task' | 'speed' | 'direction' | 'payload' | 'faults' | 'control' | 'position'>(k: K, v: Truck[K] extends Stored<infer T> | undefined ? T | undefined : never) => {
425	      if (v !== undefined) (t as unknown as Record<string, unknown>)[k] = { value: v, atLocal: at };
426	    };
427	    if (f.state !== undefined && t.state?.value !== f.state) t.stateSince = at;
428	    set('state', f.state);
429	    set('task', f.task);
430	    set('speed', f.speedMps);
431	    set('direction', f.direction);
432	    set('payload', f.payloadKg);
433	    set('faults', f.faults);
434	    set('control', f.control);
435	
436	    if (f.socPct !== undefined) {
437	      const frac = this.#isFractional(t, f.socPct);
438	      if (frac && !t.socFractional) this.#truckDq(t, 'soc_pct:fractional', `soc_pct ${f.socPct} looks like a fraction of 1, not a percentage; shown as reported`);
439	      t.socFractional = frac;
440	      t.soc = { value: f.socPct, atLocal: at };
441	    }
442	
443	    if (f.tDeviceMs !== undefined) {
444	      t.skewMs = f.tDeviceMs - this.serverNow();
445	      const flagged = Math.abs(t.skewMs) > PARAMS.deviceSkewFlagAbove.value;
446	      if (flagged && !t.skewFlagged) this.#truckDq(t, 'clock_skew', `device clock is ${(t.skewMs / 60_000).toFixed(1)} min off server time`);
447	      t.skewFlagged = flagged;
448	    }
449	
450	    if (f.position) {
451	      t.position = { value: f.position, atLocal: at };
452	      this.#trackStill(t, f.position.loopM, at);
453	    }
454	    this.#trackDrain(t, at);
455	  }
456	
457	  // A value in 0..1 is a fraction unless the pack has been draining smoothly down into it. Zero
458	  // reads the same either way.
459	  #isFractional(t: Truck, soc: number): boolean {
460	    if (soc > 1 || soc === 0) return false;
461	    const prev = t.soc?.value;
462	    if (prev === undefined || t.socFractional) return true;
463	    return prev - soc > PARAMS.fractionalSocJump.value;
464	  }
465	
466	  #trackStill(t: Truck, pos: number, at: number): void {
467	    const speed = t.speed?.value;
468	    const moving = t.state !== undefined && MOVING_STATES.has(t.state.value) && speed !== undefined && speed >= PARAMS.frozenMinReportedSpeed.value;
469	    const s = t.still;
470	    if (!s || this.#gap(pos, s.pos) >= PARAMS.frozenMaxMovement.value) {
471	      t.still = { pos, firstAt: at, lastStationaryAt: moving ? null : at, movingSince: moving ? at : null, repeats: 0 };
472	    } else if (moving) {
473	      if (s.movingSince === null) { s.movingSince = at; s.repeats = 0; } else s.repeats++;
474	    } else {
475	      s.lastStationaryAt = at;
476	      s.movingSince = null;
477	      s.repeats = 0;
478	    }
479	  }
480	
481	  #gap(a: number, b: number): number {
482	    const L = this.#site?.loopLengthM;
483	    if (!L) return Math.abs(a - b);
484	    const d = forwardDistance(L, a, b);
485	    return Math.min(d, L - d);
486	  }
487	
488	  #isContradicted(t: Truck, now: number): boolean {
489	    const s = t.still;
490	    return !!s && s.movingSince !== null && s.repeats >= 1 && now - s.movingSince >= PARAMS.frozenAfter.value;
491	  }
492	
493	  #trackDrain(t: Truck, at: number): void {
494	    const site = this.#site;
495	    const pos = t.position, soc = t.soc, payload = t.payload;
496	    // Only an interval whose ends were both reported in this message pair counts.
497	    if (!site || !pos || pos.atLocal !== at || !soc || soc.atLocal !== at || !payload || t.socFractional) return;
498	    const cur: DrainPoint = { loopM: pos.value.loopM, soc: soc.value, loaded: payload.value > 0, atLocal: at, runIndex: t.run?.index ?? 0 };
499	    const prev = t.drainPrev;
500	    t.drainPrev = cur;
501	    if (!prev || prev.runIndex !== cur.runIndex || prev.loaded !== cur.loaded || at - prev.atLocal > PARAMS.drainMaxGap.value) return;
502	    if (t.state?.value === 'CHARGING' || this.#isContradicted(t, at)) return;
503	    const drop = prev.soc - cur.soc;
504	    if (drop < 0) return;
505	    const L = site.loopLengthM;
506	    const dist = t.direction?.value === 'REV' ? forwardDistance(L, cur.loopM, prev.loopM) : forwardDistance(L, prev.loopM, cur.loopM);
507	    const plausible = (PARAMS.manualSpeedEmptyFull.value * (at - prev.atLocal)) / 1000 + PARAMS.frozenMaxMovement.value;
508	    if (dist > plausible) return;
509	    t.drain.add(cur.loaded, drop, dist);
510	  }
511	
512	  // ---- evaluation ----
513	
514	  // Precedence: no data at all; then silence, the most basic fact; then contradiction; then the age
515	  // of the position. A frozen truck that goes quiet is silent, and its range keeps the pre-freeze
516	  // anchor (#rangeOf).
517	  #confidence(t: Truck, now: number): { c: Confidence; reason: string } {
518	    if (t.lastAccepted === null) return { c: 'unknown', reason: 'no data received yet' };
519	    const silent = PARAMS.truckSilentAfter.value, old = PARAMS.truckOldAfter.value;
520	    const msgAge = now - t.lastAccepted;
521	    const frozen = this.#isContradicted(t, now);
522	    if (msgAge >= silent && t.position) {
523	      return { c: 'silent', reason: `no message for ${secs(msgAge)}${frozen ? '; its last data was frozen' : ''}` };
524	    }
525	    if (frozen) {
526	      const s = t.still!;
527	      return { c: 'contradicted', reason: `reports ${t.state?.value ?? '?'} at ${t.speed?.value ?? '?'} m/s but has not moved for ${secs(now - s.movingSince!)}` };
528	    }
529	    if (!t.position) return { c: 'unknown', reason: msgAge >= silent ? `no message for ${secs(msgAge)}, and never a valid position` : 'no valid position reported yet' };
530	    const posAge = now - t.position.atLocal;
531	    if (posAge >= silent) return { c: 'silent', reason: `no valid position for ${secs(posAge)}; messages still arriving` };
532	    if (posAge >= old) return { c: 'old', reason: `last position ${secs(posAge)} ago` };
533	    const link = this.#link;
534	    if (link && !link.up) return { c: 'old', reason: `site link down for ${secs(now - link.sinceLocal)}; last position ${secs(posAge)} ago` };
535	    return { c: 'live', reason: 'reporting normally' };
536	  }
537	
538	  #rangeOf(t: Truck, now: number, c: Confidence): { anchor: { loopM: number; atLocal: number } | null; range: Range | null } {
539	    const site = this.#site;
540	    if (!site) return { anchor: null, range: null };
541	    if (!t.position) return { anchor: null, range: { startM: 0, lengthM: site.loopLengthM } };
542	    const s = t.still;
543	    const anchor = this.#isContradicted(t, now) && s
544	      ? { loopM: s.pos, atLocal: s.lastStationaryAt ?? s.firstAt }
545	      : { loopM: t.position.value.loopM, atLocal: t.position.atLocal };
546	    const manual = t.control?.value.mode === 'MANUAL' || t.state?.value === 'MANUAL' || (t.control?.value.operatorId ?? null) !== null;
547	    const top = Math.max(t.speed?.value ?? 0, manual ? PARAMS.manualSpeedEmptyFull.value : PARAMS.autoSpeedEmpty.value);
548	    // Blunter when stale (CONTEXT.md finding 4): a silent or contradicted truck may be going either way.
549	    const canReverse = c === 'silent' || c === 'contradicted' || manual || (t.task?.value ?? null) !== null ||
550	      t.direction?.value !== 'FWD' || t.state === undefined;
551	    const elapsed = now - anchor.atLocal + PARAMS.telemetryLatencyAllowance.value;
552	    return { anchor, range: reachableRange(site.loopLengthM, anchor.loopM, elapsed, top, canReverse ? top : 0) };
553	  }
554	
555	  #battery(t: Truck, fleet: { emptyPctPerM: number | null; loadedPctPerM: number | null }, rates: Rates): BatteryView {
556	    const ownEmpty = t.drain.empty.rate(), ownLoaded = t.drain.loaded.rate();
557	    const fleetEmpty = fleetMedianExcluding(rates.empty, t.vehicleId);
558	    const fleetLoaded = fleetMedianExcluding(rates.loaded, t.vehicleId);
559	    const ratio = { empty: ownEmpty !== null && fleetEmpty ? ownEmpty / fleetEmpty : null, loaded: ownLoaded !== null && fleetLoaded ? ownLoaded / fleetLoaded : null };
560	    const flag = PARAMS.drainRatioFlag.value;
561	    const a = assess({
562	      site: this.#site, socPct: t.soc?.value, socFractional: t.socFractional, positionM: t.position?.value.loopM,
563	      loaded: t.payload ? t.payload.value > 0 : undefined, state: t.state?.value, task: t.task?.value, faults: t.faults?.value,
564	      ownEmpty, ownLoaded, fleet,
565	    });
566	    return {
567	      drain: { emptyPctPerKm: perKm(ownEmpty), loadedPctPerKm: perKm(ownLoaded), emptyEvidenceM: t.drain.empty.evidenceM, loadedEvidenceM: t.drain.loaded.evidenceM },
568	      ratioToFleet: ratio,
569	      drainHigh: (ratio.empty ?? 0) >= flag || (ratio.loaded ?? 0) >= flag,
570	      reach: a.reach, warning: a.warning, message: a.message,
571	    };
572	  }
573	
574	  #rates(): Rates {
575	    const all = [...this.#trucks.values()];
576	    return {
577	      empty: all.map((t) => ({ id: t.vehicleId, rate: t.drain.empty.rate() })),
578	      loaded: all.map((t) => ({ id: t.vehicleId, rate: t.drain.loaded.rate() })),
579	    };
580	  }
581	
582	  #fleetDrain(): { emptyPctPerM: number | null; loadedPctPerM: number | null; rates: Rates } {
583	    const rates = this.#rates();
584	    const med = (xs: Array<{ rate: number | null }>) => {
585	      const known = xs.filter((x) => x.rate !== null).map((x) => x.rate!);
586	      return known.length >= PARAMS.fleetMinTrucks.value ? median(known) : null;
587	    };
588	    return { emptyPctPerM: med(rates.empty), loadedPctPerM: med(rates.loaded), rates };
589	  }
590	
591	  #evaluate(t: Truck): void {
592	    const now = this.#clock.now();
593	    const { c, reason } = this.#confidence(t, now);
594	    if (c !== t.lastConfidence) {
595	      if (c === 'contradicted') t.frozenEpisodes++;
596	      this.#emit({ type: 'confidence', vehicleId: t.vehicleId, from: t.lastConfidence, to: c, reason, atServerMs: this.serverNow() });
597	      t.lastConfidence = c;
598	    }
599	    const fleet = this.#fleetDrain();
600	    const b = this.#battery(t, fleet, fleet.rates);
601	    const key = `${b.warning}|${b.drainHigh}`;
602	    if (key !== t.lastBattery) {
603	      if (t.lastBattery !== '' || b.warning !== null || b.drainHigh) {
604	        this.#emit({ type: 'battery', vehicleId: t.vehicleId, warning: b.warning, drainHigh: b.drainHigh, message: b.message, atServerMs: this.serverNow() });
605	      }
606	      t.lastBattery = key;
607	    }
608	  }
609	
610	  #view(t: Truck, now: number, fleet: { emptyPctPerM: number | null; loadedPctPerM: number | null; rates: Rates }): TruckView {
611	    const { c, reason } = this.#confidence(t, now);
612	    const { anchor, range } = this.#rangeOf(t, now, c);
613	    const off = this.#offset();
614	    const known = <T>(s: Stored<T> | undefined): Known<T> | null => (s ? { value: s.value, atServerMs: s.atLocal + off, ageMs: now - s.atLocal } : null);
615	    const site = this.#site;
616	    return {
617	      vehicleId: t.vehicleId,
618	      onRoster: t.onRoster,
619	      confidence: c,
620	      confidenceReason: reason,
621	      lastMessageServerMs: t.lastAccepted === null ? null : t.lastAccepted + off,
622	      ageMs: t.lastAccepted === null ? null : now - t.lastAccepted,
623	      state: known(t.state),
624	      stateSinceServerMs: t.stateSince === null ? null : t.stateSince + off,
625	      task: known(t.task),
626	      socPct: known(t.soc),
627	      socFractional: t.socFractional,
628	      speedMps: known(t.speed),
629	      direction: known(t.direction),
630	      payloadKg: known(t.payload),
631	      loaded: t.payload ? t.payload.value > 0 : null,
632	      faults: known(t.faults),
633	      control: known(t.control),
634	      position: known(t.position),
635	      anchor: anchor && { loopM: anchor.loopM, atServerMs: anchor.atLocal + off },
636	      range,
637	      mightBeIn: site && range ? zonesOverlapping(site, range) : [],
638	      frozenEpisodes: t.frozenEpisodes,
639	      skewMs: t.skewMs,
640	      skewFlagged: t.skewFlagged,
641	      run: { index: t.run?.index ?? 0, restarts: t.restarts, seq: t.run?.maxSeq ?? null },
642	      radio: { ...t.radio },
643	      dataQuality: { ...t.dq },
644	      battery: this.#battery(t, fleet, fleet.rates),
645	    };
646	  }
647	
648	  // ---- bookkeeping ----
649	
650	  #truckFor(id: string): Truck {
651	    let t = this.#trucks.get(id);
652	    if (!t) {
653	      t = new Truck(id);
654	      this.#trucks.set(id, t);
655	      if (this.#site) {
656	        t.onRoster = this.#roster.includes(id);
657	        if (!t.onRoster) this.#truckDq(t, 'unknown_vehicle', `${id} is not on the roster from hello`);
658	      }
659	    }
660	    return t;
661	  }
662	
663	  #orderedTrucks(): Truck[] {
664	    const rostered = this.#roster.map((id) => this.#trucks.get(id)).filter((t): t is Truck => !!t);
665	    const others = [...this.#trucks.values()].filter((t) => !this.#roster.includes(t.vehicleId)).sort((a, b) => a.vehicleId.localeCompare(b.vehicleId));
666	    return [...rostered, ...others];
667	  }
668	
669	  #truckDq(t: Truck, kind: string, detail: string): void {
670	    t.dq[kind] = (t.dq[kind] ?? 0) + 1;
671	    this.#emit({ type: 'data_quality', vehicleId: t.vehicleId, kind, detail, atServerMs: this.serverNow() });
672	  }
673	
674	  #linkDq(kind: string, detail: string): void {
675	    this.#dqTotal[kind] = (this.#dqTotal[kind] ?? 0) + 1;
676	    this.#dqConnection[kind] = (this.#dqConnection[kind] ?? 0) + 1;
677	    if (kind !== 'blank') this.#emit({ type: 'data_quality', vehicleId: null, kind, detail: detail.slice(0, 200), atServerMs: this.serverNow() });
678	  }
679	
680	  #sample(serverMs: number): void {
681	    this.#offsets.push(serverMs - this.#clock.now());
682	    while (this.#offsets.length > PARAMS.serverTimeSamples.value) this.#offsets.shift();
683	  }
684	
685	  #offset(): number {
686	    return this.#offsets.length ? Math.max(...this.#offsets) : 0;
687	  }
688	
689	  #emit(e: FleetEvent): void {
690	    for (const fn of this.#listeners) fn(e);
691	  }
692	}
693	
694	interface Rates {
695	  empty: Array<{ id: string; rate: number | null }>;
696	  loaded: Array<{ id: string; rate: number | null }>;
697	}
698	
699	const perKm = (x: number | null) => (x === null ? null : x * 1000);
700	const secs = (ms: number) => `${(ms / 1000).toFixed(1)} s`;
701

// Truck detail (UI.md screen 2): the words for one truck, its command timeline and its buttons. Pure:
// plain data in, plain data out; the browser only draws it, the service computes who held a truck.
//
// A command is shown as what happened to it, step by step: requested, sent, acknowledged, effect seen,
// each with its time; "retry 2 of 3"; "can't verify" when the truck's data cannot show the effect; or
// failed with the reason in words. "Accepted" is never "done" (CONTEXT.md finding 3).
import type { FleetSnapshot, TruckView } from '../fleet.ts';
import type { CommandRecord } from '../registry.ts';
import type { TruckNote } from '../trucknotes.ts';
import { age, dataState, faultWords } from '../words.ts';
import { socView } from './overview.ts';

// ---- who held a truck (L7.9) ----

export interface LeaseEnd { vehicleId: string; operatorId: string | null; event: string; reason: string | null; by: string | null; atServerMs: number }

export interface HeldBy {
  by: string | null;   // operator id, "system:<rule>", or null: not by this control room as far as it knows
  how: string;         // "HOLD", "handed back after driving", ...
  atServerMs: number | null;
}

const HOLDS: Record<string, string> = {
  HOLD: 'sent Hold',
  RELEASE_CONTROL: 'handed it back after driving',
  TAKE_CONTROL: 'took control; the controls ended and it held',
  EXIT_ZONE: 'sent it out of a zone (EXIT_ZONE); it holds outside',
  CLEAR_ESTOP: 'cleared its e-stop; it holds',
};

// For a truck reporting HOLDING: whose action left it there, from the latest of our confirmed
// commands and the site's lease events. Null when it is not holding.
export function heldBy(truck: TruckView | undefined, records: readonly CommandRecord[], leaseEnd: LeaseEnd | undefined): HeldBy | null {
  if (truck?.state?.value !== 'HOLDING') return null;
  let best: HeldBy = { by: null, how: 'held before this service saw it, or by another control-room client', atServerMs: null };
  for (const r of records) {
    if (r.vehicleId !== truck.vehicleId || r.status !== 'confirmed' || !(r.action in HOLDS)) continue;
    const at = r.effect?.serverMs ?? r.closedServerMs ?? r.createdServerMs;
    if (best.atServerMs === null || at > best.atServerMs) best = { by: actorId(r), how: HOLDS[r.action]!, atServerMs: at };
  }
  if (leaseEnd && leaseEnd.vehicleId === truck.vehicleId && leaseEnd.operatorId && (best.atServerMs === null || leaseEnd.atServerMs > best.atServerMs)) {
    const how = leaseEnd.event === 'EXPIRED' ? 'drove it; control expired with no drive input'
      : leaseEnd.event === 'RELEASED' ? 'handed it back after driving' : `lost control (${leaseEnd.reason ?? leaseEnd.event})`;
    best = { by: leaseEnd.operatorId, how, atServerMs: leaseEnd.atServerMs };
  }
  return best;
}

export function actorId(r: Pick<CommandRecord, 'actor'>): string {
  return r.actor.kind === 'operator' ? r.actor.operatorId : `system:${r.actor.rule}`;
}

// ---- the command timeline ----

export type Outcome = 'done' | 'waiting' | 'retrying' | 'queued' | 'under way' | "can't verify" | 'failed' | 'refused' | 'not sent' | 'expired' | 'cancelled' | 'replaced';

export interface Step { atServerMs: number | null; words: string; kind: 'request' | 'send' | 'ack' | 'refusal' | 'progress' | 'effect' | 'end' }

export interface TimelineEntry {
  id: string;
  action: string;
  by: string;
  why: string | null;
  outcome: Outcome;
  headline: string;      // the one line: "HOLD by priya: done", "RESUME by dave: retry 2 of 3"
  detail: string;        // the registry's summary, or the failure in words
  steps: Step[];
  open: boolean;
}

const OPEN = new Set(['pending', 'sent', 'acknowledged']);

export function timelineEntry(r: CommandRecord, truck: TruckView | undefined): TimelineEntry {
  const toServer = (localMs: number) => localMs + (r.createdServerMs - r.createdMs);
  const by = actorId(r);
  const steps: Step[] = [{ atServerMs: r.createdServerMs, kind: 'request', words: `Requested by ${by}${r.why && r.actor.kind === 'operator' ? `: "${r.why}"` : ''}` }];
  for (const a of r.attempts) {
    a.sends.forEach((s, i) => steps.push({
      atServerMs: s.serverMs, kind: 'send',
      words: s.replay ? `Sent again after reconnecting (same command, attempt ${a.n})` : a.n === 1 && i === 0 ? `Sent to the site${r.maxAttempts > 1 ? ` (attempt 1 of ${r.maxAttempts})` : ''}` : `Sent again: attempt ${a.n} of ${r.maxAttempts}`,
    }));
    if (a.ack) {
      const at = a.ack.serverMs ?? toServer(a.ack.rxMs);
      steps.push(a.ack.status === 'ACCEPTED'
        ? { atServerMs: at, kind: 'ack', words: 'Acknowledged: the site accepted it (not yet carried out)' }
        : { atServerMs: at, kind: 'refusal', words: `Refused by the site: ${a.ack.reason ?? 'no reason given'}${a.ack.holder ? ` (held by ${a.ack.holder})` : ''}` });
    } else if (a !== r.attempts.at(-1) || !OPEN.has(r.status)) {
      steps.push({ atServerMs: null, kind: 'ack', words: `No acknowledgement received for attempt ${a.n}` });
    }
  }
  if (r.queued) steps.push({ atServerMs: toServer(r.queued.sinceMs), kind: 'progress', words: `Queued at the truck behind ${r.queued.behind}${r.queued.estimateMs !== null ? ` (~${Math.round(r.queued.estimateMs / 1000)} s left)` : ''}` });
  if (r.started) steps.push({ atServerMs: toServer(r.started.atMs), kind: 'progress', words: `Under way: ${r.started.detail}` });
  if (r.effect) steps.push({ atServerMs: r.effect.serverMs, kind: 'effect', words: `Effect seen in telemetry: ${r.effect.detail}${r.effect.ackReceived ? '' : ' (no acknowledgement received)'}` });
  if (r.failure) steps.push({ atServerMs: r.closedServerMs, kind: 'end', words: r.failure.message });
  else if (r.status === 'superseded') steps.push({ atServerMs: r.closedServerMs, kind: 'end', words: 'Replaced by a newer command on this truck' });
  else if (r.status === 'cancelled') steps.push({ atServerMs: r.closedServerMs, kind: 'end', words: 'Cancelled before it was sent' });

  const n = r.attempts.length;
  const blind = truck && (truck.confidence === 'silent' || truck.confidence === 'contradicted' || truck.confidence === 'unknown');
  const blindWords = truck ? (truck.confidence === 'contradicted' ? 'data frozen' : truck.confidence === 'silent' ? 'data silent' : 'no position') : '';
  let outcome: Outcome;
  let detail = r.summary;
  switch (r.status) {
    case 'confirmed': outcome = 'done'; break;
    case 'pending': outcome = r.hold ? 'not sent' : 'waiting'; break;
    case 'sent': case 'acknowledged':
      if (blind) { outcome = "can't verify"; detail = `${r.summary}. Can't verify: ${blindWords}, so the effect cannot be seen until its data returns`; }
      else outcome = r.started ? 'under way' : r.queued ? 'queued' : n > 1 ? 'retrying' : 'waiting';
      break;
    case 'failed':
      // B16 (L2.59): a command to a truck whose data can't show the effect is "can't verify", not
      // failed. The registry reports it failed; the words here say what is known.
      if (blind && (r.failure?.code === 'NO_EFFECT' || r.failure?.code?.startsWith('EXIT_'))) {
        outcome = "can't verify";
        detail = `Can't verify: ${blindWords}. ${r.failure?.message ?? ''} Check its effect when the data returns.`;
      } else { outcome = 'failed'; detail = r.failure?.message ?? r.summary; }
      break;
    case 'refused': outcome = 'refused'; detail = r.failure?.message ?? r.summary; break;
    case 'expired': outcome = 'expired'; detail = r.failure?.message ?? r.summary; break;
    case 'cancelled': outcome = 'cancelled'; break;
    case 'superseded': outcome = 'replaced'; break;
  }
  const word = outcome === 'retrying' ? `retry ${n} of ${r.maxAttempts}`
    : outcome === 'waiting' ? (r.status === 'acknowledged' ? 'accepted, not done yet' : r.status === 'sent' ? 'sent, no answer yet' : 'about to send')
      : outcome === 'not sent' ? (r.hold?.needsReconfirm ? 'NOT sent: confirm again or cancel' : 'NOT sent yet: waiting for the site link')
        : outcome;
  return { id: r.id, action: r.action, by, why: r.why, outcome, headline: `${r.action} by ${by}: ${word}`, detail, steps, open: OPEN.has(r.status) };
}

// ---- the truck's facts ----

export interface Fact { label: string; value: string; flag?: boolean }

export function truckFacts(t: TruckView, snap: FleetSnapshot, note: TruckNote | undefined, held: HeldBy | null, you: string | null): Fact[] {
  const out: Fact[] = [];
  const p = t.position;
  out.push({ label: 'Data', value: t.confidence === 'live' ? 'live' : `${dataState(t)}: ${t.confidenceReason}`, flag: t.confidence !== 'live' });
  out.push({ label: 'State', value: [t.state?.value, t.task?.value].filter(Boolean).join(' · ') || 'not reported' });
  out.push({ label: 'Where', value: p ? `${p.value.zoneId}, ${p.value.segmentId} at ${p.value.offsetM.toFixed(1)} m${t.confidence === 'live' ? '' : `, reported ${age(p.ageMs)} ago`}${t.confidence === 'silent' || t.confidence === 'contradicted' ? `; could be in ${t.mightBeIn.join(', ') || 'anywhere'}` : ''}` : 'no valid position' });
  if (t.speedMps) out.push({ label: 'Speed', value: `${t.speedMps.value.toFixed(1)} m/s ${t.direction?.value === 'REV' ? 'reversing' : 'forward'}${t.loaded === null ? '' : t.loaded ? ', loaded' : ', empty'}` });
  const soc = socView(t);
  out.push({ label: 'Battery', value: `${soc.text} (the pack's own figure)${soc.flags.length ? `; ${soc.flags.join('; ')}` : ''}`, flag: soc.flags.length > 0 });
  const d = t.battery.drain, r = t.battery.ratioToFleet, f = snap.fleetDrain;
  const drain = (own: number | null, fleet: number | null, ratio: number | null, kind: string) => own === null ? null : `${kind} ${own.toFixed(1)} %/km${fleet !== null ? ` against the fleet's ${fleet.toFixed(1)}` : ''}${ratio !== null ? ` (${ratio.toFixed(1)}×)` : ''}`;
  const drains = [drain(d.emptyPctPerKm, f.emptyPctPerKm, r.empty, 'empty'), drain(d.loadedPctPerKm, f.loadedPctPerKm, r.loaded, 'loaded')].filter(Boolean);
  out.push({ label: 'Drain', value: drains.length ? drains.join('; ') : 'not measured yet (needs about 60 m of travel)', flag: t.battery.drainHigh });
  if (t.battery.reach.toBay) out.push({ label: 'To the bay', value: `${t.battery.reach.toBay.distanceM.toFixed(0)} m ${t.battery.reach.toBay.direction === 'FWD' ? 'forward' : 'back'}, needs about ${t.battery.reach.toBay.needPct.toFixed(1)} %` });
  const c = t.control?.value;
  out.push({ label: 'Control', value: c ? `${c.mode}${c.operatorId ? `, driven by ${c.operatorId === you ? 'you' : c.operatorId}` : ''}${c.deadman ? ', stopped by its deadman' : ''}` : 'not reported' });
  if (held) out.push({ label: 'Held by', value: held.by ? `${held.by === you ? 'you' : held.by}: ${held.how}` : held.how });
  const faults = note?.faults ?? [];
  const now = faultWords(t);
  if (faults.length || now) {
    out.push({
      label: 'Faults', flag: true,
      value: faults.length ? faults.map((x) => `${x.code}${x.endedServerMs === null ? '' : ' (cleared)'}: ${x.alreadyPresent ? 'already present when first seen' : `from ${age(snap.atServerMs - x.sinceServerMs)} ago`}${x.where ? `, in ${x.where.zoneId} (${x.where.segmentId} at ${x.where.offsetM.toFixed(0)} m)` : ''}`).join('; ') : now!,
    });
  } else out.push({ label: 'Faults', value: 'none' });
  out.push({ label: 'Clock', value: t.skewMs === null ? 'not reported' : `device clock ${fmtSkew(t.skewMs)} server time${t.skewFlagged ? ': its own timestamps are ignored; ages use server time' : ''}`, flag: t.skewFlagged });
  const restarts = note?.restarts ?? [];
  out.push({ label: 'Controller restarts', value: restarts.length ? restarts.map((x) => `${age(snap.atServerMs - x.atServerMs)} ago`).join(', ') : t.run.restarts ? `${t.run.restarts}` : 'none seen' });
  return out;
}

function fmtSkew(ms: number): string {
  const a = Math.abs(ms);
  const words = a >= 60_000 ? `${(a / 60_000).toFixed(1)} min` : `${(a / 1000).toFixed(1)} s`;
  return a < 1_000 ? 'within a second of' : `${words} ${ms > 0 ? 'ahead of' : 'behind'}`;
}

// ---- buttons ----

export interface Button {
  action: 'HOLD' | 'RESUME' | 'RETURN_TO_BAY' | 'EXIT_ZONE' | 'TAKE_CONTROL' | 'RELEASE_CONTROL';
  label: string;
  force?: true;
  primary?: boolean;
  disabled?: string;   // why it can't be pressed, in words
  note?: string;       // what pressing it will do, when that is not obvious
}

// Every button the operator may want. Most stay pressable whatever the truck is doing: the safety
// check and the site decide, and a refusal says why and what would allow it. Only what can never
// work is disabled, with the reason.
export function buttons(t: TruckView, you: { id: string; role: string } | null, held: HeldBy | null): Button[] {
  const c = t.control?.value;
  const holder = c?.mode === 'MANUAL' ? c.operatorId : null;
  const mine = holder !== null && holder === you?.id;
  const depleted = (t.faults?.value ?? []).includes('BATTERY_DEPLETED');
  const heldByYou = held?.by !== undefined && held.by === you?.id;
  const out: Button[] = [
    { action: 'HOLD', label: 'Hold' },
    { action: 'RESUME', label: heldByYou ? 'Resume (you held it)' : 'Resume', primary: heldByYou },
    { action: 'RETURN_TO_BAY', label: 'Return to bay' },
    { action: 'EXIT_ZONE', label: 'Exit zone', note: 'Leaves the zone it is in when the site accepts it, by the nearer end: it may reverse' },
  ];
  if (mine) out.push({ action: 'RELEASE_CONTROL', label: 'Release control', primary: true, note: 'Hands it back; it holds until someone resumes it' });
  else if (depleted) out.push({ action: 'TAKE_CONTROL', label: 'Take control', disabled: 'Battery depleted: it needs a tow and cannot be driven' });
  else if (holder) {
    out.push({ action: 'TAKE_CONTROL', label: 'Take control', disabled: `${holder} is driving it. Talk to them${you?.role === 'supervisor' ? ', or take over' : '; a supervisor can take over'}` });
    if (you?.role === 'supervisor') out.push({ action: 'TAKE_CONTROL', label: `Take over from ${holder}`, force: true, note: `Takes the controls from ${holder} at once; they are told who took it` });
  } else out.push({ action: 'TAKE_CONTROL', label: 'Take control', note: 'Stops it at once and waits for drive input; interrupts loading, dumping or charging' });
  return out;
}
