493	function send(msg: Record<string, unknown>): string | null {
494	  if (!socket || socket.readyState !== WebSocket.OPEN) return null;
495	  const ref = `b${++refN}`;
496	  socket.send(JSON.stringify({ ...msg, ref }));
497	  return ref;
