511	// The e-stop state of one truck, in a word: our open command first, then the truck's own report.
512	// "stopped" only when the truck itself says ESTOPPED.
513	function estopWord(truck: string, live: LiveState, snap: FleetSnapshot): { word: string; kind: string } {
514	  const t = snap.trucks.find((x) => x.vehicleId === truck);
515	  const c = live.commands.find((x) => x.vehicleId === truck && x.action === 'ESTOP');
516	  if (c?.needsReconfirm) return { word: 'NOT sent', kind: 'reconfirm' };
517	  if (c?.waitingForLink) return { word: 'pending', kind: 'pending' };
518	  if (c && c.open) return { word: 'sent', kind: 'sent' };
519	  if (c && (c.status === 'failed' || c.status === 'expired')) return { word: 'NOT done', kind: 'failed' };
520	  if (t?.state?.value === 'ESTOPPED') return { word: 'stopped', kind: 'stopped' };
521	  return { word: 'STOP', kind: 'ready' };
522	}
523	
524	function renderEstops(): void {
525	  const live = frame?.live;
526	  const snap = frame?.snapshot;
527	  const box = $('estop-trucks');
528	  if (!live || !snap) return;
529	  const ids = snap.trucks.filter((t) => t.onRoster !== false).map((t) => t.vehicleId);
530	  // Buttons keep their element between frames, so a press is never lost to a redraw.
531	  const have = new Map([...box.querySelectorAll<HTMLButtonElement>('button')].map((b) => [b.dataset.truck!, b]));
532	  const buttons = ids.map((id) => {
533	    let b = have.get(id);
534	    if (!b) {
535	      b = el('button', { type: 'button', class: 'estop-truck', 'data-truck': id }, el('b', {}, id), el('span', {}, 'STOP'));
536	      b.addEventListener('click', () => estop(id));
537	    }
538	    const s = estopWord(id, live, snap);
539	    b.dataset.kind = s.kind;
540	    b.lastElementChild!.textContent = s.word;
541	    b.setAttribute('aria-label', `E-stop ${id}: ${s.word}`);
542	    return b;
543	  });
544	  if (buttons.length !== box.children.length || buttons.some((b, i) => box.children[i] !== b)) box.replaceChildren(...buttons);
545	
546	  // E-stops waiting for the link, needing confirmation again, or not done: each says so, with what to do.
547	  const list = $('estop-pending');
548	  const waiting = live.commands.filter((c) => c.action === 'ESTOP' && (c.waitingForLink || (!c.open && (c.status === 'failed' || c.status === 'expired'))));
549	  const rows = new Map([...list.querySelectorAll<HTMLElement>('.estop-row')].map((r) => [r.dataset.id!, r]));
550	  const out = waiting.map((c) => {
551	    let r = rows.get(c.id);
552	    if (!r) {
553	      r = el('div', { class: 'banner down estop-row', 'data-id': c.id, 'data-truck': c.vehicleId }, el('span', { class: 'text' }));
554	      if (c.waitingForLink) {
555	        const again = el('button', { type: 'button', class: 'again' }, 'Confirm e-stop again');
556	        again.addEventListener('click', () => { if (send({ type: 'reconfirm', recordId: c.id }) === null) estopNote('NOT sent: the service is disconnected.', true); });
557	        const cancel = el('button', { type: 'button', class: 'cancel' }, 'Cancel');
558	        cancel.addEventListener('click', () => { if (send({ type: 'cancel', recordId: c.id }) === null) estopNote('NOT cancelled: the service is disconnected.', true); });
559	        r.append(again, cancel);
560	      }
561	    }
562	    r.dataset.kind = c.needsReconfirm ? 'reconfirm' : c.waitingForLink ? 'pending' : 'failed';
563	    r.querySelector<HTMLElement>('.text')!.textContent = `E-stop ${c.vehicleId} (pressed by ${c.by}): ${c.summary}`;
564	    const again = r.querySelector<HTMLButtonElement>('button.again');
565	    if (again) again.hidden = !c.needsReconfirm;
566	    const cancel = r.querySelector<HTMLButtonElement>('button.cancel');
567	    if (cancel) cancel.hidden = !c.waitingForLink;
