158	async function shot(p: Page, name: string, selector?: string): Promise<void> {
159	  if (!SHOTS) return;
160	  // Clipped from the whole page at the top, so the sticky header never covers the element.
161	  await p.evaluate(() => window.scrollTo(0, 0));
162	  const box = selector ? await (await p.$(selector))!.boundingBox() : null;
163	  const inDrawer = selector ? await p.$eval(selector, (e) => getComputedStyle(e).position === 'fixed') : false;
164	  if (box && !inDrawer) await p.screenshot({ path: join(SHOTS, name), fullPage: true, clip: box });
165	  else if (box) await (await p.$(selector!))!.screenshot({ path: join(SHOTS, name) });
166	  else await p.screenshot({ path: join(SHOTS, name) });
167	}
