388	// End to end: the real service (`node src/main.ts`, a child process) against the fake gateway over
389	// TLS (fake/tls.ts) on 127.0.0.1, on the real clock. The certificate is made with openssl at test time
390	// in a temporary directory and deleted after; the service trusts it through NODE_EXTRA_CA_CERTS, a
391	// Node feature, so the product has no test-only trust code. The child's environment is built from
392	// scratch: nothing from the developer's shell (or a .env) leaks in, and it can never reach the real
393	// gateway.
394	import assert from 'node:assert/strict';
395	import { spawn, spawnSync, type ChildProcess } from 'node:child_process';
396	import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
397	import { request } from 'node:http';
398	import { tmpdir } from 'node:os';
399	import { join } from 'node:path';
400	import WebSocket from 'ws';
401	import { SystemClock } from '../../src/clock.ts';
402	import { hashPassword } from '../../src/users.ts';
403	import { DEFAULT_BEHAVIOUR } from '../../fake/behaviour.ts';
404	import { DLH1 } from '../../fake/dlh1.ts';
405	import { LIVE_DAY, planTrucks, type Faults } from '../../fake/faults.ts';
406	import { FakeGateway, type Connection } from '../../fake/gateway.ts';
407	import type { Blasts, TruckInit } from '../../fake/model.ts';
408	import { listenTls, type TlsServer } from '../../fake/tls.ts';
409	
410	export const HAVE_OPENSSL = !spawnSync('openssl', ['version'], { stdio: 'ignore' }).error;
411	export const MAIN = new URL('../../src/main.ts', import.meta.url).pathname;
412	export const EMAIL = '<redacted-email>';
