414	export function tempDir(prefix: string): { dir: string; cleanup(): void } {
415	  const dir = mkdtempSync(join(tmpdir(), prefix));
416	  return { dir, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
417	}
