427	export class FakeSite {
428	  readonly gw: FakeGateway;
429	  readonly lines: string[] = [];   // every line received from any client, as received
430	  logins = 0;                      // connections that sent a valid auth line
431	  #server: TlsServer | null = null;
432	  #port = 0;
433	  readonly #tls: { key: Buffer; cert: Buffer };
434	  readonly seed: number;
435	  readonly faults: Faults;
436	
437	  constructor(tls: { key: Buffer; cert: Buffer }, o: { seed?: number; faults?: Faults; blasts?: Blasts; trucks?: TruckInit[] } = {}) {
438	    this.#tls = tls;
439	    this.seed = o.seed ?? 11;
440	    this.faults = o.faults ?? LIVE_DAY;
441	    this.gw = new FakeGateway(new SystemClock(), { seed: this.seed, site: DLH1, blasts: o.blasts ?? 'random', faults: this.faults, ...(o.trucks ? { trucks: o.trucks } : {}) });
442	    const receive = this.gw.receive.bind(this.gw);
443	    this.gw.receive = (conn: Connection, line: string) => {
444	      this.lines.push(line);
445	      const wasAuthed = conn.authed;
446	      receive(conn, line);
447	      if (!wasAuthed && conn.authed) this.logins++;
448	    };
449	    this.gw.start();
450	  }
