470	
471	  // Trucks the fake's live day leaves alone (no telemetry fault planned), so their telemetry can
472	  // confirm a command.
473	  cleanTrucks(): string[] {
474	    const plan = planTrucks(this.faults, DLH1.vehicles, DEFAULT_BEHAVIOUR, this.seed);
475	    const busy = new Set(Object.values(plan).map((p) => p?.vehicle));
476	    return DLH1.vehicles.filter((v) => !busy.has(v));
