511	// Starts `node src/main.ts` with exactly this environment (plus PATH), and waits for "listening on".
512	export async function startServiceProcess(env: Record<string, string>, o: { cwd?: string; timeoutMs?: number } = {}): Promise<RunningService> {
513	  const child = spawn(process.execPath, [MAIN], { cwd: o.cwd, env: { PATH: process.env.PATH ?? '/usr/bin:/bin', ...env }, stdio: ['ignore', 'pipe', 'pipe'] });
514	  let out = '';
515	  child.stdout!.setEncoding('utf8').on('data', (c: string) => { out += c; });
516	  child.stderr!.setEncoding('utf8').on('data', (c: string) => { out += c; });
517	  const exited = new Promise<number | null>((resolve) => child.once('exit', (code) => resolve(code)));
518	  const url = await new Promise<string>((resolve, reject) => {
519	    const deadline = setTimeout(() => reject(new Error(`service did not start:\n${out}`)), o.timeoutMs ?? 20_000);
520	    const check = () => {
521	      const m = /listening on (http:\/\/127\.0\.0\.1:\d+\/)/.exec(out);
522	      if (m) { clearTimeout(deadline); resolve(m[1]!); }
523	    };
524	    child.stdout!.on('data', check);
525	    void exited.then((code) => { clearTimeout(deadline); reject(new Error(`service exited with ${code} before listening:\n${out}`)); });
526	  });
527	  const port = Number(new URL(url).port);
528	  return {
529	    child, url, port, origin: `http://127.0.0.1:${port}`, output: () => out, exited,
530	    stop: async () => { if (child.exitCode === null) child.kill('SIGTERM'); return exited; },
531	  };
532	}
