536	export function http(port: number, method: string, path: string, o: { headers?: Record<string, string>; body?: string } = {}): Promise<Res> {
537	  return new Promise((resolve, reject) => {
538	    const req = request({ host: '127.0.0.1', port, method, path, agent: false, headers: { host: `127.0.0.1:${port}`, ...o.headers } }, (res) => {
539	      let body = '';
540	      res.setEncoding('utf8');
541	      res.on('data', (c: string) => { body += c; });
542	      res.on('end', () => resolve({ status: res.statusCode!, headers: res.headers, body }));
543	    });
544	    req.on('error', reject);
545	    if (o.body !== undefined) req.write(o.body);
546	    req.end();
547	  });
548	}
