560	// A browser's live connection: every message it got, and a way to wait for one.
561	export class LiveClient {
562	  readonly messages: Array<Record<string, any>> = [];
563	  closeCode: number | null = null;
564	  readonly ws: WebSocket;
565	  readonly opened: Promise<void>;
566	
567	  constructor(s: RunningService, cookie: string) {
568	    this.ws = new WebSocket(`ws://127.0.0.1:${s.port}/api/live`, { headers: { origin: s.origin, cookie } });
569	    this.ws.on('message', (d) => { try { this.messages.push(JSON.parse(String(d))); } catch { /* not ours */ } });
570	    this.ws.on('close', (code) => { this.closeCode = code; });
571	    this.ws.on('error', () => { /* close follows */ });
572	    this.opened = new Promise((resolve, reject) => { this.ws.once('open', () => resolve()); this.ws.once('unexpected-response', (_q, r) => reject(new Error(`upgrade refused: ${r.statusCode}`))); });
573	  }
574	
575	  frames(): Array<Record<string, any>> { return this.messages.filter((m) => m.type === 'frame'); }
576	  lastFrame(): Record<string, any> | undefined { return this.frames().at(-1); }
577	  results(): Array<Record<string, any>> { return this.messages.filter((m) => m.type === 'result'); }
578	
579	  send(m: unknown): void { this.ws.send(typeof m === 'string' ? m : JSON.stringify(m)); }
580	
581	  // Sends a message with a ref and waits for its result.
582	  async ask(m: Record<string, unknown>, timeoutMs = 5_000): Promise<Record<string, any>> {
583	    const ref = `t${Math.random().toString(36).slice(2, 10)}`;
584	    this.send({ ...m, ref });
585	    return waitFor(() => this.results().find((r) => r.ref === ref), timeoutMs, `result for ${JSON.stringify(m)}`);
586	  }
587	
588	  close(): void { this.ws.close(); }
589	}
590	
591	export async function waitFor<T>(fn: () => T | undefined | null | false, timeoutMs: number, what: string): Promise<T> {
592	  const start = Date.now();
593	  for (;;) {
594	    const v = fn();
595	    if (v) return v;
596	    if (Date.now() - start > timeoutMs) throw new Error(`timed out after ${timeoutMs} ms waiting for ${what}`);
597	    await new Promise((r) => setTimeout(r, 50));
598	  }
599	}
