    assert.match(replies.find((r) => r.drive?.code === 'ZONE_CLOSED')!.error, /^Stopped: DECLINE is CLOSED, \d+ m ahead\. Driving forward into it is refused; you can drive the other way\.$/);
    const last = h.drives().at(-1)!;
