import { chromium } from 'playwright-core';
const b = await chromium.launch({ channel: 'chrome', headless: true });
const p = await b.newPage();
await p.setContent('<table><tbody id="rows"><tr data-truck="A"><td class="id">A</td></tr></tbody></table>');
await p.evaluate(() => {
  window.got = 0; window.detached = 0;
  document.getElementById('rows').addEventListener('click', () => window.got++);
  const tr = document.querySelector('tr');
  const swap = () => { const td = document.createElement('td'); td.className = 'id'; td.textContent = 'A'; tr.replaceChildren(td); setTimeout(swap, 0); };
  swap();
});
let n = 0;
for (let i = 0; i < 300; i++) { await p.$eval('#rows tr[data-truck="A"] td.id', (td) => { if (!td.isConnected) window.detached++; td.click(); }); n++; }
console.log('clicks', n, 'reached #rows', await p.evaluate(() => window.got), 'detached at click', await p.evaluate(() => window.detached));
await b.close();

